/**
 * Seed catalog: counts, geography, opening hours, photos, translations, nearby search and the
 * class timetable (supabase/seed.sql, generated by supabase/seed/generate.mjs).
 */
import { asAnon, runInTransaction } from '../_harness/db';
import { ANCHOR, CITY_CENTRE, one, rows } from './helpers';

const CYRILLIC = /[Ѐ-ӿ]/;
/** docs/COPY.md: Uzbek uses ʻ (U+02BB) and ʼ (U+02BC), never ASCII or curly quotes. */
const WRONG_UZ_APOSTROPHE = /['`‘’]/;

describe('seed: catalog', () => {
  test('3 active plans, 12 categories all in use, at least 25 active venues', async () => {
    const counts = await one<{ plans: number; categories: number; active: number; unused: number }>(
      `select (select count(*)::int from public.plans where active) as plans,
              (select count(*)::int from public.venue_categories) as categories,
              (select count(*)::int from public.venues where status = 'active') as active,
              (select count(*)::int from public.venue_categories c
                where not exists (select 1 from public.venues v
                                  where v.category_id = c.id and v.status = 'active')) as unused`,
    );
    expect(counts).toEqual({ plans: 3, categories: 12, active: expect.any(Number), unused: 0 });
    expect(counts.active).toBeGreaterThanOrEqual(25);
  });

  test('plans follow the price list (integer UZS)', async () => {
    const plans = await rows(
      `select code, price_uzs, visits_per_month, max_venue_tier, per_venue_monthly_cap,
              jsonb_array_length(perks) > 0 as has_perks
       from public.plans order by sort`,
    );
    expect(plans).toEqual([
      {
        code: 'basic',
        price_uzs: 199000,
        visits_per_month: 8,
        max_venue_tier: 1,
        per_venue_monthly_cap: 4,
        has_perks: true,
      },
      {
        code: 'standard',
        price_uzs: 349000,
        visits_per_month: 16,
        max_venue_tier: 2,
        per_venue_monthly_cap: 8,
        has_perks: true,
      },
      {
        code: 'premium',
        price_uzs: 599000,
        visits_per_month: 99,
        max_venue_tier: 3,
        per_venue_monthly_cap: 99,
        has_perks: true,
      },
    ]);
  });

  test('every venue is inside Tashkent (41.25-41.37, 69.18-69.38) in a real district', async () => {
    const outside = await rows(
      `select slug, lat, lng, district, tz from public.venues
       where lat not between 41.25 and 41.37 or lng not between 69.18 and 69.38 or tz <> 'Asia/Tashkent'
          or district not in ('yunusabad', 'chilanzar', 'mirzo-ulugbek', 'yakkasaray', 'mirabad',
                              'shaykhantahur', 'sergeli', 'almazar')`,
    );
    expect(outside).toEqual([]);
    const districts = await one<{ n: number }>(
      `select count(distinct district)::int as n from public.venues`,
    );
    expect(districts.n).toBe(8);
  });

  test('every venue has hours for all 7 weekdays and 2-5 photos with a placeholder', async () => {
    const problems = await rows(
      `select v.slug,
              (select count(distinct weekday)::int from public.venue_hours h where h.venue_id = v.id) as weekdays,
              (select count(*)::int from public.venue_photos p where p.venue_id = v.id) as photos
       from public.venues v
       where (select count(distinct weekday) from public.venue_hours h where h.venue_id = v.id) <> 7
          or (select count(*) from public.venue_photos p where p.venue_id = v.id) not between 2 and 5`,
    );
    expect(problems).toEqual([]);
    const badPhotos = await rows(
      `select path from public.venue_photos
       where path !~ '^https://picsum\\.photos/seed/[a-z0-9-]+/1200/800$' or length(blurhash) <> 28`,
    );
    expect(badPhotos).toEqual([]);
  });

  test('women_only_hours summarises the women-only venue_hours rows', async () => {
    const mismatched = await rows(
      `select v.slug from public.venues v
       where coalesce(v.women_only_hours, '[]'::jsonb) is distinct from coalesce(
         (select jsonb_agg(jsonb_build_object('weekday', h.weekday, 'opens', to_char(h.opens, 'HH24:MI'),
                                              'closes', to_char(h.closes, 'HH24:MI'))
                           order by h.weekday, h.opens)
          from public.venue_hours h where h.venue_id = v.id and h.women_only), '[]'::jsonb)`,
    );
    expect(mismatched).toEqual([]);
    const withWindows = await one<{ n: number }>(
      `select count(*)::int as n from public.venues where women_only_hours is not null`,
    );
    expect(withWindows.n).toBeGreaterThanOrEqual(3);
  });

  test('translations: ru/uz/en present everywhere, uz in Latin with ʻ/ʼ, en without Cyrillic', async () => {
    const values = await rows<{
      source: string;
      value: Record<string, unknown>;
      ru_cyrillic: boolean;
      valid: boolean;
    }>(
      `select source, value, ru_cyrillic, public.jsonb_i18n_valid(value) as valid from (
         select 'venue_categories.name:' || slug as source, name as value, true as ru_cyrillic from public.venue_categories
         union all select 'venues.name:' || slug, name, false from public.venues
         union all select 'venues.description:' || slug, description, true from public.venues
         union all select 'venues.address:' || slug, address, true from public.venues
         union all select 'plans.name:' || code, name, false from public.plans
         union all select 'plans.perks:' || code, perk, true from public.plans, jsonb_array_elements(perks) perk
         union all select 'class_templates.name:' || id, name, false from public.class_templates
         union all select 'class_templates.description:' || id, description, true from public.class_templates
         union all select 'trainers.bio:' || id, bio, true from public.trainers
         union all select 'notifications.title:' || id, title, true from public.notifications
         union all select 'notifications.body:' || id, body, true from public.notifications
       ) x`,
    );
    expect(values.length).toBeGreaterThan(300);
    const problems = values.flatMap(({ source, value, ru_cyrillic, valid }) => {
      const text = (locale: string) =>
        typeof value[locale] === 'string' ? (value[locale] as string) : '';
      const issues: string[] = [];
      if (!valid) issues.push('jsonb_i18n_valid');
      for (const locale of ['ru', 'uz', 'en'])
        if (text(locale).trim() === '') issues.push(`missing ${locale}`);
      if (CYRILLIC.test(text('uz')) || WRONG_UZ_APOSTROPHE.test(text('uz')))
        issues.push(`uz: ${text('uz')}`);
      if (CYRILLIC.test(text('en'))) issues.push(`en: ${text('en')}`);
      if (ru_cyrillic && !CYRILLIC.test(text('ru'))) issues.push(`ru: ${text('ru')}`);
      return issues.map((issue) => `${source} ${issue}`);
    });
    expect(problems).toEqual([]);
  });

  test('rpc_nearby_venues from the city centre finds at least 10 active venues within 5 km (anon)', async () => {
    await runInTransaction(async (client) => {
      await asAnon(client);
      const { rows: nearby } = await client.query<{
        slug: string;
        distance_m: number;
        status: string;
      }>(`select slug, distance_m, status from public.rpc_nearby_venues($1, $2, 5000)`, [
        CITY_CENTRE.lat,
        CITY_CENTRE.lng,
      ]);
      expect(nearby.length).toBeGreaterThanOrEqual(10);
      expect(nearby.every((v) => v.status === 'active' && v.distance_m <= 5000)).toBe(true);
      const distances = nearby.map((v) => v.distance_m);
      expect(distances).toEqual([...distances].sort((a, b) => a - b));
    });
  });
});

describe('seed: class timetable', () => {
  test('every active venue has scheduled classes in the 14 days from the anchor date', async () => {
    const missing = await rows(
      `select v.slug from public.venues v
       where v.status = 'active' and not exists (
         select 1 from public.class_sessions s
         where s.venue_id = v.id and s.status = 'scheduled'
           and s.starts_at >= $1::timestamptz and s.starts_at < $1::timestamptz + interval '14 days')`,
      [ANCHOR],
    );
    expect(missing).toEqual([]);
    const late = await one<{ n: number }>(
      `select count(*)::int as n from public.class_sessions
       where starts_at >= $1::timestamptz + interval '14 days'
          or (status = 'scheduled' and starts_at < $1::timestamptz)
          or (status = 'completed' and starts_at >= $1::timestamptz)`,
      [ANCHOR],
    );
    expect(late.n).toBe(0);
  });

  test('session counters match bookings: booked_count = seats taken, waitlist only when full', async () => {
    const mismatched = await rows(
      `select s.id, s.capacity, s.booked_count, s.waitlist_count,
              count(b.id) filter (where b.status in ('confirmed', 'checked_in', 'no_show'))::int as seats,
              count(b.id) filter (where b.status = 'waitlisted')::int as waiting
       from public.class_sessions s left join public.bookings b on b.class_session_id = s.id
       group by s.id
       having s.booked_count <> count(b.id) filter (where b.status in ('confirmed', 'checked_in', 'no_show'))
           or s.waitlist_count <> count(b.id) filter (where b.status = 'waitlisted')
           or s.booked_count > s.capacity
           or (s.waitlist_count > 0 and s.booked_count < s.capacity)`,
    );
    expect(mismatched).toEqual([]);
  });
});
